{"path": "/app/bin/tally.py", "content": "#!/usr/bin/env python3
"""Ranked-choice tally. Usage: tally.py INPUT_DIR OUTPUT_FILE (rules in /app/docs)."""
import csv
import io
import json
import os
import re
import sys
import unicodedata
from collections import Counter


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    out = []
    for ch in s:
        cat = unicodedata.category(ch)
        out.append(ch if (cat[0] == "L" or cat == "Nd") else " ")
    return " ".join("".join(out).split())


def to_int(v):
    if isinstance(v, bool):
        raise ValueError(v)
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        return int(v)
    return int(str(v).strip())


# ---------------------------------------------------------------- reading files

def read_text(path):
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        return f.read()


def parse_csv(path):
    text = read_text(path).replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    meta = {}
    i = 0
    while i < len(lines):
        ln = lines[i]
        if ln.strip() == "":
            i += 1
            continue
        if ln.lstrip().startswith("#"):
            body = ln.lstrip()[1:]
            if ":" in body:
                k, v = body.split(":", 1)
                meta.setdefault(k.strip().lower(), v.strip())
            i += 1
            continue
        break
    rest = "\n".join(lines[i:])
    rows = [r for r in csv.reader(io.StringIO(rest, newline="")) if r and any(c.strip() for c in r)]
    records = []
    if rows:
        header = [h.strip().lower() for h in rows[0]]
        idx = {}
        rank_cols = {}
        for j, h in enumerate(header):
            m = re.fullmatch(r"rank\s*(\d+)", h)
            if m:
                rank_cols.setdefault(int(m.group(1)), j)
            elif h not in idx:
                idx[h] = j
        bi, ci = idx.get("ballot"), idx.get("contest")
        for r in rows[1:]:
            contest = r[ci] if ci is not None and ci < len(r) else ""
            ballot = r[bi] if bi is not None and bi < len(r) else ""
            ranks = {}
            for n, j in rank_cols.items():
                cell = r[j] if j < len(r) else ""
                marks = []
                if cell.strip():
                    for part in cell.split("|"):
                        p = part.strip()
                        if not p:
                            continue
                        if p[:3].upper() == "WI:":
                            marks.append(("w", p[3:]))
                        else:
                            marks.append(("c", p))
                ranks[n] = marks
            records.append((ballot, contest.strip() if False else contest, ranks))
    return meta, records


def parse_jsonl(path):
    meta = None
    records = []
    for ln in read_text(path).split("\n"):
        if not ln.strip():
            continue
        obj = json.loads(ln)
        if meta is None:
            meta = {str(k).lower(): v for k, v in obj.items()}
            continue
        ranks = {}
        for m in obj.get("marks") or []:
            try:
                n = to_int(m.get("rank"))
            except (ValueError, TypeError):
                continue
            lst = ranks.setdefault(n, [])
            if m.get("candidate") is not None:
                lst.append(("c", str(m["candidate"]).strip()))
            elif m.get("write_in") is not None:
                lst.append(("w", str(m["write_in"])))
        records.append((obj.get("ballot"), obj.get("contest"), ranks))
    return meta or {}, records


def load_batches(cvr_dir):
    best = {}
    try:
        names = sorted(os.listdir(cvr_dir))
    except OSError:
        names = []
    for name in names:
        path = os.path.join(cvr_dir, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            meta, recs = parse_csv(path)
        elif name.endswith(".jsonl"):
            meta, recs = parse_jsonl(path)
        else:
            continue
        batch = str(meta.get("batch", "")).strip()
        try:
            rev = to_int(meta.get("revision", 0))
        except (ValueError, TypeError):
            rev = 0
        status = str(meta.get("status", "final")).strip().lower()
        cur = best.get(batch)
        if cur is None or rev > cur[0]:
            best[batch] = (rev, status, recs)
    out = []
    for batch in sorted(best):
        rev, status, recs = best[batch]
        if status != "void":
            out.append(recs)
    return out


# ---------------------------------------------------------------- counting

SKIP, PASS, CHOICE, OVER = "skip", "pass", "choice", "over"


def read_ballot(ranks, max_ranks, writein_map, withdrawn, known):
    """Return tuple of (kind, candidate-or-None) per ranking 1..max_ranks."""
    seen = set()
    result = []
    for n in range(1, max_ranks + 1):
        marks = set()
        for kind, val in ranks.get(n, ()):
            if kind == "c":
                marks.add(norm_id(val))
            else:
                c = writein_map.get(norm_text(val))
                if c is not None:
                    marks.add(c)
        if not marks:
            result.append((SKIP, None))
            continue
        marks -= withdrawn
        if not marks:
            result.append((PASS, None))
            continue
        left = marks - seen
        seen |= marks
        if not left:
            result.append((SKIP, None))
        elif len(left) == 1:
            result.append((CHOICE, next(iter(left))))
        else:
            result.append((OVER, None))
    return tuple(result)


def count_for(ballot, continuing):
    """Candidate key the ballot counts for, or None when exhausted."""
    n = len(ballot)
    for i, (kind, c) in enumerate(ballot):
        if kind == CHOICE:
            if c in continuing:
                return c
        elif kind == OVER:
            return None
        elif kind == SKIP:
            if i + 1 < n and ballot[i + 1][0] == SKIP:
                return None
        # PASS: go on
    return None


def run_contest(contest, records):
    max_ranks = to_int(contest.get("max_ranks", 0))
    cands = {}  # normalized -> original id
    withdrawn = set()
    for c in contest.get("candidates", []):
        k = norm_id(c["id"])
        cands[k] = c["id"]
        if str(c.get("status", "active")).strip().lower() == "withdrawn":
            withdrawn.add(k)
    writein_map = {}
    for c in contest.get("candidates", []):
        pass
    wi_ids = []
    for w in contest.get("write_ins", []):
        k = norm_id(w["id"])
        cands[k] = w["id"]
        wi_ids.append(k)
        for t in [w.get("name", "")] + list(w.get("aliases", [])):
            writein_map.setdefault(norm_text(t), k)
    # a write-in text equal to a printed candidate's name is not qualified,
    # unless it is listed for a qualified write-in (handled by writein_map)
    lot = [norm_id(x) for x in contest.get("lot_order", [])]
    lot_pos = {k: i for i, k in enumerate(lot)}

    sigs = Counter()
    for ranks in records:
        sigs[read_ballot(ranks, max_ranks, writein_map, withdrawn, cands)] += 1
    total = len(records)

    order = [k for k in cands if k not in withdrawn]
    continuing = set(order)
    history = []  # list of dict k -> votes
    rounds = []
    winner = None
    while True:
        tallies = {k: 0 for k in order if k in continuing}
        exhausted = 0
        for sig, cnt in sigs.items():
            c = count_for(sig, continuing)
            if c is None:
                exhausted += cnt
            else:
                tallies[c] += cnt
        history.append(tallies)
        active = total - exhausted
        rnd = {"round": len(history),
               "tallies": {cands[k]: v for k, v in tallies.items()},
               "exhausted": exhausted, "eliminated": []}
        rounds.append(rnd)
        if active == 0:
            break
        top = max(tallies, key=lambda k: tallies[k]) if tallies else None
        if len(continuing) == 1:
            winner = next(iter(continuing))
            break
        if top is not None and tallies[top] * 2 > active:
            winner = top
            break
        zeros = [k for k, v in tallies.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            low = min(tallies.values())
            tied = [k for k, v in tallies.items() if v == low]
            r = len(history) - 2
            while len(tied) > 1 and r >= 0:
                m = min(history[r][k] for k in tied)
                tied = [k for k in tied if history[r][k] == m]
                r -= 1
            if len(tied) > 1:
                tied.sort(key=lambda k: lot_pos.get(k, -1))
                tied = [tied[-1]]
            elim = tied
        rnd["eliminated"] = sorted(cands[k] for k in elim)
        continuing -= set(elim)
    return {"contest": contest["id"], "ballots": total,
            "winner": cands[winner] if winner is not None else None,
            "rounds": rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, "election.json"), "r", encoding="utf-8-sig") as f:
        election = json.load(f)
    by_contest = {c["id"]: [] for c in election["contests"]}
    for recs in load_batches(os.path.join(inp, "cvr")):
        for ballot, contest, ranks in recs:
            if contest in by_contest:
                by_contest[contest].append(ranks)
    result = {"election": election.get("election"),
              "contests": [run_contest(c, by_contest[c["id"]]) for c in election["contests"]]}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)
        f.write("\n")


if __name__ == "__main__":
    main()
